package solution

import "sync"

func Merge(cs ...<-chan int) <-chan int {
	out := make(chan int)
	var wg sync.WaitGroup
	wg.Add(len(cs)) // one outstanding forwarder per input
	for _, c := range cs {
		go func(c <-chan int) {
			defer wg.Done()      // mark this forwarder done
			for v := range c {   // drain this input until it closes
				out <- v
			}
		}(c)
	}
	go func() { wg.Wait(); close(out) }() // single closer
	return out
}

